package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Comentario en el historial de una novedad (tabla SEGUIMIENTO_INCIDENTE, RF-M7-03).
 * <p>
 * EN: Comment in the history of an incident (SEGUIMIENTO_INCIDENTE table, RF-M7-03).
 */
@Entity
@Table(name = "SEGUIMIENTO_INCIDENTE")
public class IncidentFollowUp {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id de la novedad. EN: The incident id. */
    @Column(name = "INCIDENTE_ID", nullable = false) private Long incidentId;
    /** El usuario que escribió. EN: The user who wrote it. */
    @Column(name = "USUARIO", nullable = false, length = 30) private String username;
    /** El texto del comentario. EN: The comment text. */
    @Column(name = "COMENTARIO", nullable = false, length = 500) private String comment;
    /** La fecha en minutos de reloj. EN: The date in clock minutes. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FECHA", nullable = false) private Double date;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected IncidentFollowUp() {}

    /**
     * Crea un comentario de seguimiento.
     * <p>
     * EN: Creates a follow-up comment.
     *
     * @param incidentId id de la novedad / incident id
     * @param username usuario que escribe / user who writes
     * @param comment texto del comentario / comment text
     * @param date fecha en minutos de reloj / date in clock minutes
     */
    public IncidentFollowUp(long incidentId, String username, String comment, double date) {
        this.incidentId = incidentId; this.username = username; this.comment = comment; this.date = date;
    }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id de la novedad.
     * <p>
     * EN: Returns the incident id.
     *
     * @return el id de la novedad / the incident id
     */
    public Long getIncidentId() { return incidentId; }

    /**
     * Devuelve el usuario que escribió.
     * <p>
     * EN: Returns the user who wrote it.
     *
     * @return el usuario que escribió / the user who wrote it
     */
    public String getUsername() { return username; }

    /**
     * Devuelve el texto del comentario.
     * <p>
     * EN: Returns the comment text.
     *
     * @return el texto del comentario / the comment text
     */
    public String getComment() { return comment; }

    /**
     * Devuelve la fecha en minutos de reloj.
     * <p>
     * EN: Returns the date in clock minutes.
     *
     * @return la fecha en minutos de reloj / the date in clock minutes
     */
    public Double getDate() { return date; }
}
